import {
  ChangeDetectionStrategy,
  Component,
  computed,
  DestroyRef,
  effect,
  ElementRef,
  inject,
  signal,
  Signal,
  viewChild,
} from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { NavigationEnd, Router } from '@angular/router';
import { NgbModal, NgbTooltip } from '@ng-bootstrap/ng-bootstrap';
import { filter, map, withLatestFrom } from 'rxjs';
import { componentId } from '../../../../utils/DOM';
import { capitalize } from '../../../../utils/string';
import { HotkeyDirective } from '../../../_directives/hotkey.directive';
import { OverviewItem } from '../../../_models/overview';
import {
  SearchableArticleKind
} from '../../../_models/search';
import { HotkeyService } from '../../../_services/hotkey.service';
import { OnlineService } from '../../../_services/online.service';
import { Icon } from '../../../design/atoms/_models/icon';
import { ButtonComponent } from '../../../design/atoms/button/button.component';
import { IconComponent } from '../../../design/atoms/icon/icon.component';
import { PlaceholderComponent } from '../../../design/atoms/placeholder/placeholder.component';
import {
  SEARCH_TOGGLES,
  Toggle,
} from '../../../design/molecules/_models/toggle';
import {
  ListEntry,
  ListEntryTemplateContext,
} from '../../../design/molecules/list/list.component';
import { OverviewEntryComponent } from '../../../design/molecules/overview-entry/overview-entry.component';
import { SearchFieldComponent } from '../../../design/molecules/search-field/search-field.component';
import { ToggleRowComponent } from '../../../design/molecules/toggle-row/toggle-row.component';
import { getMetadataForType } from '../../../design/organisms/_model/sidebar';
import { GlobalStore } from '../../../global.store';
import { SearchPageStore } from './search-page.store';

type SearchEntry = Pick<
  OverviewItem,
  'name' | 'description' | 'images' | 'article_type'
> & {
  url: string;
  color: string | undefined;
  icon: Icon;
};

@Component({
  selector: 'app-search-modal',
  imports: [
    ButtonComponent,
    HotkeyDirective,
    SearchFieldComponent,
    OverviewEntryComponent,
    IconComponent,
    NgbTooltip,
    ToggleRowComponent,
    PlaceholderComponent,
  ],
  templateUrl: './search-modal.component.html',
  styleUrl: './search-modal.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SearchModalComponent {
  readonly modalService = inject(NgbModal);
  readonly hotkeyService = inject(HotkeyService);
  readonly globalStore = inject(GlobalStore);
  readonly onlineService = inject(OnlineService);
  readonly searchStore = inject(SearchPageStore);
  readonly router = inject(Router);
  readonly destroyRef = inject(DestroyRef);

  private readonly listElement: Signal<ElementRef<HTMLElement> | undefined> =
    viewChild('list', {
      read: ElementRef<HTMLElement>,
    });

  readonly id = componentId();
  readonly titleId = `${this.id}-title`;
  readonly listId = `${this.id}-list`;
  readonly DEFAULT_URL = 'assets/default_images/icon_default.webp';

  readonly campaignName = this.globalStore.campaignName;
  readonly activeFilters = signal<SearchableArticleKind[]>([]);
  readonly filterToggles = computed(() => {
    const activeFilterSet = new Set(this.activeFilters());
    return SEARCH_TOGGLES.map((toggle) => ({
      ...toggle,
      active: toggle.value.every((filterKind) =>
        activeFilterSet.has(filterKind),
      ),
    }));
  });
  readonly searchString = signal('');

  readonly isLoading = computed(
    () => this.searchStore.searchArticlesQueryState() === 'loading',
  );
  readonly isEmptySearch = computed(() => {
    const hasEntries =
      (this.searchStore.searchArticles()?.articles?.length ?? 0) > 0;
    const hasLoaded = this.searchStore.searchArticlesQueryState() === 'success';
    return hasLoaded && !hasEntries;
  });

  readonly entries = computed(() => {
    const articles = this.searchStore.searchArticles()?.articles;
    return articles?.map((article) => {
      const metadata = getMetadataForType(article.article_type);
      const isDiaryEntry = article.article_type === 'diaryentry';

      return {
        data: {
          name: isDiaryEntry ? article.name_full : article.name,
          description: article.description,
          url: article.getAbsoluteRouterUrl(),
          color: metadata?.color,
          icon: metadata?.iconClass as Icon,
          article_type: capitalize(article.article_type),
        },
        trackId: `${article.article_type}-${article.pk}`,
        ariaText: {
          kind: 'aria-labelledby',
          id: `overview-entry-${article.article_type}-${article.pk}`,
        },
      } satisfies ListEntry<SearchEntry>;
    });
  });

  constructor() {
    const hasCurrentCampaign$ = toObservable(
      this.globalStore.currentCampaign,
    ).pipe(map((campaign) => !!campaign));

    this.hotkeyService
      .watchAction('search')
      .pipe(
        withLatestFrom(hasCurrentCampaign$, this.onlineService.online$),
        filter(
          ([, hasCurrentCampaign, isOnline]) => hasCurrentCampaign && isOnline,
        ),
        takeUntilDestroyed(),
      )
      .subscribe(() => this.openModal());

    effect(() => {
      const searchString = this.searchString();
      if (!searchString) return;

      this.searchStore.loadSearchArticles({
        searchString: searchString,
        filters: this.activeFilters(),
      });
    });

    this.closeSearchOnRouteChange();
  }

  updateFilters(event: Toggle<SearchableArticleKind[]>) {
    if (event.active) {
      this.activeFilters.update((filters) => [...filters, ...event.value]);
    } else {
      this.activeFilters.update((filters) =>
        filters.filter((f) => !event.value.includes(f)),
      );
    }
  }

  routeToEntry(data: SearchEntry) {
    this.router.navigateByUrl(data.url);
    this.modalService.dismissAll();
  }

  typecastContext(context: unknown) {
    return context as ListEntryTemplateContext<SearchEntry>;
  }

  openModal() {
    if (this.modalService.hasOpenModals()) return;

    this.modalService.open(SearchModalComponent, {
      centered: true,
      ariaLabelledBy: this.titleId,
      modalDialogClass: 'search-modal',
      beforeDismiss: () => {
        this.searchStore.reset();
        return true;
      },
    });
  }

  dismiss() {
    this.modalService.dismissAll();
  }

  shiftToSearch() {
    this.listElement()?.nativeElement.focus();
  }

  /**
   * Route Change means the user clicked on a link somewhere, therefore we want to close the search
   */
  private closeSearchOnRouteChange() {
    this.router.events
      .pipe(
        filter((event) => event instanceof NavigationEnd),
        takeUntilDestroyed(this.destroyRef),
      )
      .subscribe(() => this.modalService.dismissAll());
  }
}
